	while (!net_pkt_read_u8(pkt, &type)) {
		if (type == DHCPV4_OPTIONS_END) {
			NET_DBG("options_end");
			goto end;
		}

		/* RFC 2132: Options 0 (PAD) and 255 (END) are fixed-length
		 * options without a length byte. All other options have a
		 * length byte following the tag octet.
		 */
		if (type == DHCPV4_OPTIONS_PAD) {
			/* PAD option has no length byte, just skip it */
			continue;
		}

		if (net_pkt_read_u8(pkt, &length)) {
			NET_ERR("option parsing, bad length");
			return false;
		}
